import {Replay,primaryAction} from './replay.js';
import {FrameMetrics,assess} from './metrics.js';
const $=id=>document.getElementById(id),reduced=matchMedia('(prefers-reduced-motion: reduce)').matches;
let scene,clock,data,manifest,selected,speed=1,raf=0,last=0,uiAt=0,run=null,report=null,contextLost=false,live=new FrameMetrics(),longTaskObserver;
const number=(value,digits=0)=>Number.isFinite(value)?value.toLocaleString('tr-TR',{maximumFractionDigits:digits}):'—';
function displayMetrics(metrics){if(scene?.renderer.isSoftwareRenderer){for(const id of ['fps','p95','draws','tris'])$(id).textContent='—';return;}$('fps').textContent=number(metrics.fps,1);$('p95').textContent=number(metrics.p95Ms,1);$('draws').textContent=number(metrics.drawCallsMax);$('tris').textContent=number(metrics.trianglesMax);}
function select(key){const model=scene.models.get(key);if(!model)return;selected=key;scene.select(key);inspector();}
function inspector(){const m=scene.models.get(selected);if(!m)return;const h=m.hero;$('hero-name').textContent=h.name;$('hero-role').textContent=(h.role==='tank'?'TANK':'MENZİLLİ BÜYÜCÜ')+' · '+(h.lane==='front'?'ÖN SAF':'ARKA SAF');$('hero-hp').textContent=h.hp+' / '+h.maxHp;$('hero-shield').textContent=h.shield||0;$('hero-description').textContent=h.role==='tank'?'Hedefine yürür, çekiciyle vurur ve ön saftaki yerine döner.':'Arka saftaki yerini korur. Asa hareketiyle büyü yollar; hasar hedefe ulaşınca görünür.';
 for(const type of ['tank','mage']){const active=(h.role==='tank')===(type==='tank');$(type).classList.toggle('active',active);$(type).setAttribute('aria-pressed',String(active));}}
function hud(teams,round=1){teams.forEach((team,side)=>{const prefix=side?'red':'blue';$(prefix+'-hp').value=100*team.reduce((s,h)=>s+h.hp,0)/team.reduce((s,h)=>s+h.maxHp,0);$(prefix+'-count').textContent=team.filter(h=>h.hp>0).length+' / 5 kahraman';});$('round').textContent=String(round).padStart(2,'0');inspector();}
function buttons(){const playing=clock.playing;$('play').textContent=clock.finished?'↻ Tekrar izle':playing?'Ⅱ Duraklat':clock.cursor||clock.started?'▶ Devam et':'▶ Savaşı başlat';$('play').setAttribute('aria-pressed',String(playing));$('phase').textContent=clock.finished?'BİTTİ':playing?'SAVAŞ':clock.cursor||clock.started?'DURAKLADI':'HAZIR';}
function describe(frame){const e=primaryAction(frame);if(!e){$('action').textContent='Yeni tur · Kahramanlar sıradaki hamleye hazırlanıyor.';return;}
 if(String(e.actor).startsWith('commander:')){$('action').textContent='Komutan etkisi · '+(e.action.includes('support')?'Destek: motorun iyileştirme kaydı':'Savunma: motorun kalkan kaydı');return;}
 const actor=scene.models.get(e.side+':'+e.actor)?.hero.name||'Kahraman',target=frame.teams.flat().find(h=>h.id===e.target)?.name;
 $('action').textContent=actor+(target?' → '+target:'')+(e.action==='stun-skip'?' · Saldırı atlandı':e.value?' · '+e.value+' etki':'');}
function motionPhase(name){document.querySelectorAll("[data-motion]").forEach(el=>el.classList.toggle("active",el.dataset.motion===name));}
function reset(start=false){motionPhase(null);clock.reset();scene.reset(data.initial);hud(data.initial);$('result').hidden=true;$('action').textContent='Takımlar hazır. Tanklar önde, menzilli kahramanlar arkada.';live.reset();$('progress').style.width='0%';$('elapsed').textContent='0 / '+data.frames.length;if(start)clock.play();buttons();last=0;}
function stopLoop(){cancelAnimationFrame(raf);raf=0;last=0;}
function startLoop(){if(!raf&&!contextLost&&!document.hidden)raf=requestAnimationFrame(tick);}
function recordReport(valid,reason=''){
 if(!run)return;const result=run.metrics.result(),environment={userAgent:navigator.userAgent,platform:navigator.userAgentData?.platform||navigator.platform,hardwareConcurrency:navigator.hardwareConcurrency||null,viewport:{width:innerWidth,height:innerHeight},canvas:{cssWidth:scene.width,cssHeight:scene.height,bufferWidth:scene.canvas.width,bufferHeight:scene.canvas.height},devicePixelRatio:devicePixelRatio,profile:scene.quality,reducedMotion:reduced,webglVersion:scene.renderer.getContext().getParameter(scene.renderer.getContext().VERSION),renderer:scene.renderer.getContext().getParameter(scene.renderer.getContext().RENDERER),longTasksSupported:run.longTasksSupported};
 report={schema:1,prototype:'hero-auction-mobile3d',at:new Date().toISOString(),sourceCommit:manifest.sourceCommit,environment,valid,reason,acceptance:assess(result,{valid,complete:valid}),metrics:result,load:{readyMs:scene.loadMs,note:'Includes module, replay and GLB decode; may use warm browser cache.'},resources:{geometriesStart:run.geometriesStart,geometriesEnd:scene.renderer.info.memory.geometries,texturesStart:run.texturesStart,texturesEnd:scene.renderer.info.memory.textures},build:manifest.totals,scope:'Browser rendering measurement only; not a physical Android WebView certification. No GPU timing or APK delta measured.'};
 $('diagnostics').textContent=JSON.stringify(report,null,2);$('download').disabled=false;$('test-status').textContent=valid?(report.acceptance==='pass'?'Tamamlandı · Bu cihazda hedefler karşılandı.':'Tamamlandı · Bu cihazda akıcılık hedefleri incelenmeli.'):'Ölçüm geçersiz · '+reason;displayMetrics(result);run=null;$('benchmark').textContent='30 saniyelik testi başlat ↗';$('benchmark').disabled=false;for(const id of ['play','speed','reset','quality','camera','camera-reset','closeup','tank','mage'])$(id).disabled=false;scene.controls.setEnabled(true);clock.pause();buttons();stopLoop();
}
function tick(now){raf=0;if(scene.renderer.isSoftwareRenderer&&last&&now-last<32){startLoop();return;}const ms=last?now-last:0;last=now;
 if(clock.finished&&run)reset(true);
 clock.advance(ms/1000*speed);scene.render(clock.playing||run?ms/1000*speed:0,clock.progress);
 if(live.samples.length>300)live.reset();if(ms>0&&!scene.renderer.isSoftwareRenderer)live.add(ms,scene.renderer.info);
 if(run){const age=now-run.started;
  if(age>=3000){if(run.sampleStart===null){run.sampleStart=now;run.geometriesStart=scene.renderer.info.memory.geometries;run.texturesStart=scene.renderer.info.memory.textures;}else run.metrics.add(ms,scene.renderer.info);}
  if(now-uiAt>450){$('test-status').textContent=age<3000?'Isınma · '+Math.ceil((3000-age)/1000)+' sn':'Ölçüm · '+Math.max(0,Math.ceil(30-(now-run.sampleStart)/1000))+' sn kaldı';}
  if(run.sampleStart!==null&&now-run.sampleStart>=30000){recordReport(true);return;}
 }
 if(now-uiAt>450){uiAt=now;displayMetrics(run&&run.sampleStart!==null?run.metrics.result():live.result());$('elapsed').textContent=clock.cursor+' / '+data.frames.length;$('progress').style.width=(100*clock.cursor/data.frames.length)+'%';}
 if(clock.playing||run)startLoop();else {last=0;buttons();}
}
function invalidate(reason){scene?.controls.clear();if(run)recordReport(false,reason);clock?.pause();buttons();stopLoop();}
function showError(error){$('loading').hidden=false;$('loading').replaceChildren();const title=document.createElement('strong');title.textContent='3D önizleme açılamadı';const description=document.createElement('p');description.textContent=error.message||'Yükleme başarısız oldu.';const retry=document.createElement('a');retry.href='./';retry.textContent='Yeniden yükle';$('loading').append(title,description,retry);for(const id of ['play','benchmark','camera','quality','reset','speed','tank','mage'])$(id).disabled=true;$('renderer-badge').textContent='GRAFİK YOK';}
async function boot(){const loadStarted=performance.now();try{
 const [module,replayResponse,manifestResponse]=await Promise.all([import('./scene.js'),fetch('./replay.json'),fetch('./build-info.json')]);if(!replayResponse.ok||!manifestResponse.ok)throw Error('Savaş kaydı yüklenemedi.');data=await replayResponse.json();manifest=await manifestResponse.json();
 scene=new module.MobileArena($('arena'),$('labels'),$('floats'),{onSelect:select,reduced});await scene.load();scene.loadMs=performance.now()-loadStarted;scene.onLabelSelect=select;scene.setTeams(data.initial);selected='0:'+data.initial[0][0].id;
 clock=new Replay(data,{start(frame,index,plan){scene.start(frame,plan);describe(frame);$('round').textContent=String(frame.round).padStart(2,'0');},phase(name,frame,index,plan){motionPhase(["skip","round"].includes(plan.kind)?null:name);},impact(frame){scene.impact(frame);hud(frame.teams,frame.round);},end(){scene.end();motionPhase(null);},finish(){if(!run){$('progress').style.width='100%';$('elapsed').textContent=data.frames.length+' / '+data.frames.length;$('result').hidden=false;$('winner').textContent=data.winner===null?'Denge bozulmadı':data.winner===0?'Mavi takım kazandı':'Kızıl takım kazandı';buttons();}}});
 select(selected);hud(data.initial);scene.render(0,0);$('loading').hidden=true;$('play').disabled=false;$('benchmark').disabled=!!scene.renderer.isSoftwareRenderer;if(scene.renderer.isSoftwareRenderer){$('renderer-badge').textContent='YAZILIM';$('test-status').textContent='WebGL 2 bu tarayıcıda kapalı. Görsel önizleme açık; GPU performans testi kullanılamıyor.';}$('arena').dataset.ready='true';$('size-note').textContent='Bağımsız paket · '+number(manifest.totals.gzipBytes/1024,0)+' KB gzip';$('elapsed').textContent='0 / '+data.frames.length;
 $('closeup').onclick=()=>{clock.pause();stopLoop();scene.focus(scene.focusKey?null:selected);$('closeup').setAttribute('aria-pressed',String(!!scene.focusKey));$('closeup').textContent=scene.focusKey?'Arenaya dön ↙':'Modeli yakından incele ↗';buttons();};
 $('play').onclick=()=>{if(scene.focusKey){scene.focus(null);$('closeup').setAttribute('aria-pressed','false');$('closeup').textContent='Modeli yakından incele ↗';}if(clock.finished)reset(true);else if(clock.playing){clock.pause();stopLoop();}else clock.play();buttons();if(clock.playing)startLoop();};
 $('reset').onclick=()=>{invalidate('Kayıt sıfırlandı.');reset();};$('replay-result').onclick=()=>{reset(true);startLoop();};$('speed').onclick=()=>{speed=speed===1?1.5:speed===1.5?2:1;$('speed').textContent=speed+'×';};$('camera').onclick=()=>{scene.cameraNext();};$('camera-reset').onclick=()=>scene.resetCamera();$('quality').onchange=()=>{if(run)invalidate('Görüntü profili değişti.');scene.setQuality($('quality').value);live.reset();};
 for(const type of ['tank','mage'])$(type).onclick=()=>select('0:'+data.initial[0][type==='tank'?0:2].id);
 $('benchmark').onclick=()=>{scene.controls.setEnabled(false);scene.focus(null);$('closeup').setAttribute('aria-pressed','false');$('closeup').textContent='Modeli yakından incele ↗';speed=1;$('speed').textContent='1×';reset(true);run={metrics:new FrameMetrics(),started:performance.now(),sampleStart:null,longTasksSupported:typeof PerformanceObserver!=='undefined'&&PerformanceObserver.supportedEntryTypes.includes('longtask')};$('download').disabled=true;report=null;$('diagnostics').textContent='Ölçüm sürüyor.';for(const id of ['play','speed','reset','quality','camera','camera-reset','closeup','tank','mage'])$(id).disabled=true;$('benchmark').disabled=true;$('benchmark').textContent='Test çalışıyor…';$('test-status').textContent='Isınma · 3 sn';startLoop();};
 $('download').onclick=()=>{if(!report)return;const url=URL.createObjectURL(new Blob([JSON.stringify(report,null,2)],{type:'application/json'})),a=document.createElement('a');a.href=url;a.download='hero-auction-3d-'+new Date().toISOString().replace(/[:.]/g,'-')+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);};
 if(typeof PerformanceObserver!=='undefined'&&PerformanceObserver.supportedEntryTypes.includes('longtask')){longTaskObserver=new PerformanceObserver(list=>{if(run?.sampleStart!==null&&run)for(const e of list.getEntries())if(e.startTime>=run.sampleStart){run.metrics.longTasks++;run.metrics.longTaskMs+=e.duration;}});longTaskObserver.observe({type:'longtask',buffered:false});}
 document.addEventListener('visibilitychange',()=>{if(document.hidden)invalidate('Sekme arka plana alındı.');});
 window.addEventListener('pagehide',event=>{invalidate('Sayfadan ayrılındı.');if(!event.persisted){longTaskObserver?.disconnect();scene.dispose();}});
 window.addEventListener('pageshow',event=>{if(event.persisted){last=0;scene.resize();scene.render(0,clock.progress);}});
 window.addEventListener('resize',()=>{scene.controls.clear();if(run)invalidate('Ekran boyutu veya yönü değişti.');});
 $('arena').addEventListener('webglcontextlost',event=>{event.preventDefault();contextLost=true;invalidate('WebGL bağlamı kayboldu.');showError(Error('Grafik bağlantısı kesildi. Önizlemeyi yeniden yükle.'));});
 }catch(error){console.error(error);scene?.dispose();showError(error);}}
void boot();
